          "3": {
            "title": "3. Danger of Pride",
            "snippet": "Wealth must not lead to self-congratulation."
          },
          "4": {
            "title": "4. Desert's Lesson",
            "snippet": "People live by divine word, not bread alone."
          },
          "5": {
            "title": "5. Land of Springs",
            "snippet": "The promised land brings physical and spiritual abundance."
          },
