        "chabadInsight": "Le Sanctuaire extérieur reflète celui que chacun bâtit en son cœur, faisant de sa maison et de ses actes une demeure pour Dieu.",
        "halachaFocus": "Respect des synagogues et des objets sacrés, et charité volontaire (tsédaka).",
