        "haftarah": "1 Rois 18:20 – 18:39 (Élie sur le mont Carmel)",
        "rashiInsight": "Rachi associe le demi-sicle à la prudence envers le recensement direct : la contribution égale unit aussi les riches et les pauvres.",
        "chabadInsight": "Après le veau d'or, Dieu révèle les Treize Attributs de Miséricorde : le repentir sincère peut restaurer une relation blessée.",
        "halachaFocus": "Sainteté du Chabbat, gravité de sa transgression, et règles du pardon et de l'expiation.",
