      "noaj": {
        "name": "Noaj",
        "summary": "Noé constrói a arca; seguem-se o Dilúvio, a aliança do arco-íris e a Torre de Babel.",
        "bookSpanish": "Gênesis",
        "reference": "Gênesis 6:9 – 11:32",
        "haftarah": "Isaías 54:1 – 55:5",
        "rashiInsight": "Rashi comenta a expressão “Noach era um homem justo e íntegro em suas gerações”. Alguns sábios o elogiam: se foi justo numa geração corrupta, quanto mais seria entre os justos. Outros fazem uma ressalva: em comparação com sua geração era justo, mas diante de Abraão sua fé necessitava de apoio divino.",
        "chabadInsight": "O Baal Shem Tov e o Rebe explicam que, em hebraico, “teivá” significa tanto “arca” quanto “palavra”. Quando as águas das preocupações materiais nos cercam, devemos entrar na teivá: as palavras sagradas da Torá e da tefilá (oração), que protegem e elevam a alma.",
        "halachaFocus": "Os sete mandamentos dos filhos de Noach: proibição da idolatria, blasfêmia, homicídio, relações sexuais proibidas, roubo e consumo de parte de um animal ainda vivo, além do dever de estabelecer tribunais de justiça.",
        "aliyot": {
          "1": {
            "description": "Noach é um homem justo; Deus ordena que construa a Arca com medidas exatas."
          },
          "2": {
            "description": "Noach, sua família e os animais puros e impuros entram na Arca."
          },
          "3": {
            "description": "As águas do Dilúvio prevalecem; o corvo e a pomba com o ramo de oliveira."
          },
          "4": {
            "description": "A saída da Arca, a oferenda de Noach e os sete mandamentos universais (Leis Noaíticas)."
          },
          "5": {
            "description": "A aliança divina simbolizada pelo arco-íris (Ot HaBrit)."
          },
          "6": {
            "description": "A vinha de Noach, seus filhos Shem, Cham e Yéfet e a tabela das setenta nações."
          },
          "7": {
            "description": "A Torre de Babel, a confusão das línguas e a linhagem até Abraão."
          }
        },
        "jasidicLessons": {
          "1": {
            "title": "1. A Arca Interior",
            "snippet": "Entrar na teivá significa encontrar abrigo nas palavras sagradas da oração durante as tempestades interiores."
          },
          "2": {
            "title": "2. A Janela da Consciência",
            "snippet": "O tzohar, a luz da Arca, ilumina até os períodos de maior escuridão coletiva."
          },
          "3": {
            "title": "3. A Bondade Universal",
            "snippet": "Noach alimentou os animais incansavelmente, ensinando compaixão ativa por toda criatura."
          },
          "4": {
            "title": "4. A Aliança do Arco-Íris",
            "snippet": "As cores do arco-íris representam diferentes almas unidas sob a misericórdia divina."
          },
          "5": {
            "title": "5. A Torre de Babel",
            "snippet": "A união motivada pela arrogância destrói a comunicação verdadeira; a unidade precisa de valores."
          },
          "6": {
            "title": "6. A Fumaça do Sacrifício",
            "snippet": "A gratidão de Noach após o Dilúvio amenizou a severidade do julgamento no mundo."
          },
          "7": {
            "title": "7. Sementes de Renovação",
            "snippet": "Toda catástrofe pessoal pode esconder terreno fértil para um novo começo espiritual."
          },
          "8": {
            "title": "8. O Valor do Tempo",
            "snippet": "A paciência dentro da Arca demonstra a disciplina necessária aos processos de cura."
          },
          "9": {
            "title": "9. A Terra Habitada",
            "snippet": "Povoar o mundo significa preenchê-lo com consciência moral e reconhecimento do Criador."
          },
          "10": {
            "title": "10. Além do Julgamento",
            "snippet": "A promessa da aliança assegura que a compaixão divina sustenta continuamente o universo."
          }
        }
      },
